-- name: Coldain_War_Controller
-- enabled: true
-- actors: world
-- timers: world
-- Source: ../eqmacemu/greatdivide/encounters/Ring10.lua
-- Generated by scripts/quests/coldain-ring-ten.mjs; edit coldain_ring_ten.json.
-- Supported-chain verification: docs/coldain-ring-war-verification.md.
local item_lib = require("items")
local function staging(e)
 return e.qglobals.coldainWarPhase=="staging" and e.qglobals.coldainWarStaging=="active"
end

function event_signal(e)
 if e.signal==1 and staging(e) and not e.qglobals.coldainWarController then
  eq.set_global("coldainWarController","started",3,"M30")
  eq.set_timer("staging_reveal",10000)
  eq.set_timer("staging_deadline",1800000)
 elseif e.signal==2 then
  require("coldain_ring_war").begin(e)
 elseif e.signal==3 then
  require("coldain_ring_war").fail(e)
 end
end
function event_timer(e)
 if e.timer:sub(1,4)=="war_" then require("coldain_ring_war").timer(e);return end
 if e.timer=="staging_reveal" then
  eq.stop_timer(e.timer)
  if staging(e) then
   eq.spawn_condition("greatdivide",0,24,1)
   -- Conditions publish on the existing one-second world clock. Freeze the
   -- walker only after publication assigns its actual spawn lifetime.
   eq.set_timer("launch_walker",1000)
  end
 elseif e.timer=="launch_walker" then
  if not staging(e) then eq.stop_timer(e.timer);return end
  assert(eq.get_entity_list():IsMobSpawnedByNpcTypeID(2000967),"walking Badain has not been published")
  eq.signal(2000967,1)
  eq.stop_timer(e.timer)
 elseif e.timer=="staging_deadline" then
  eq.stop_timer(e.timer)
  if e.qglobals.coldainWarPhase=="staging" then
   eq.stop_all_timers()
   eq.spawn_condition("greatdivide",0,23,0)
   eq.spawn_condition("greatdivide",0,148,0)
   eq.spawn_condition("greatdivide",0,24,0)
   eq.spawn_condition("greatdivide",0,25,0)
   eq.spawn_condition("greatdivide",0,27,1)
   eq.del_global("coldainWarStaging")
   eq.del_global("coldainWarController")
   eq.del_global("coldainWarPhase")
  end
 end
end
